export * from './ThemeContext.js';

import React, { createContext, useContext, useState, ReactNode } from 'react';

type Theme = 'light' | 'dark' | 'system';

interface Colors {
  primary: string;
  secondary: string;
  background: string;
  surface: string;
  text: string;
  border: string;
}

interface ThemeContextType {
  theme: Theme;
  isDark: boolean;
  colors: Colors;
  setTheme: (theme: Theme) => void;
  toggleTheme: () => void;
}

const lightColors: Colors = {
  primary: '#007AFF',
  secondary: '#5856D6',
  background: '#FFFFFF',
  surface: '#F2F2F7',
  text: '#000000',
  border: '#C6C6C8',
};

const darkColors: Colors = {
  primary: '#0A84FF',
  secondary: '#5E5CE6',
  background: '#000000',
  surface: '#1C1C1E',
  text: '#FFFFFF',
  border: '#38383A',
};

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

interface ThemeProviderProps {
  children: ReactNode;
}

export function ThemeProvider({ children }: ThemeProviderProps) {
  const [theme, setTheme] = useState<Theme>('system');

  // For React Native apps, this would need to be connected to the actual system theme
  // For now, defaulting to light mode when system is selected
  const isDark = theme === 'dark';
  const colors = isDark ? darkColors : lightColors;

  const toggleTheme = () => {
    setTheme(theme === 'dark' ? 'light' : 'dark');
  };

  return (
    <ThemeContext.Provider value={{ theme, isDark, colors, setTheme, toggleTheme }}>
      {children}
    </ThemeContext.Provider>
  );
}

interface Colors {
  primary: string;
  secondary: string;
  background: string;
  surface: string;
  text: string;
  border: string;
  neutral: {
    50: string;
    100: string;
    400: string;
    500: string;
    700: string;
    900: string;
    950: string;
  };
}

